<?php
require __DIR__.'/bootstrap.php';
if(session_status()!==PHP_SESSION_ACTIVE){
    $recoveryCookiePath = rtrim(dirname(isset($_SERVER['SCRIPT_NAME']) ? $_SERVER['SCRIPT_NAME'] : '/upgrade/recovery.php'), '/');
    $recoveryCookiePath = ($recoveryCookiePath === '' || $recoveryCookiePath === '.') ? '/' : $recoveryCookiePath.'/';
    session_set_cookie_params(0, $recoveryCookiePath, '', UMEUtil::isHttps(), true);
    session_start();
}
function recJson($d,$s=200){http_response_code($s);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function recSecurityLog($storage,$event,$details=array()){$row=array('time'=>UMEUtil::now(),'event'=>$event);foreach($details as $k=>$v)$row[$k]=$v;$json=json_encode($row,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($json!==false)UMEUtil::appendLine(rtrim($storage,'/').'/security-events.log',$json);}
$authorized=!empty($_SESSION['ume_recovery_site'])&&$_SESSION['ume_recovery_site']===(string)$config['site_id']&&!empty($_SESSION['ume_recovery_expires'])&&(int)$_SESSION['ume_recovery_expires']>=time();
$error='';$requestMessage='';
if(isset($_GET['ticket'])&&isset($_GET['signature'])){
    try{$ticket=$selfUpdater->verifyRecoveryTicket((string)$_GET['ticket'],(string)$_GET['signature'],$auth->adminEmail());session_regenerate_id(true);$_SESSION['ume_recovery_site']=(string)$config['site_id'];$_SESSION['ume_recovery_expires']=time()+900;$_SESSION['ume_recovery_csrf']=UMEUtil::randomHex(24);recSecurityLog($manager->storage(),'recovery_email_login',array('ticket_nonce_hash'=>hash('sha256',(string)$ticket['nonce']),'expires_at'=>(int)$_SESSION['ume_recovery_expires']));header('Location: recovery.php');exit;}
    catch(Exception $e){$error=$e->getMessage();}catch(Throwable $e){$error='Recovery-ссылка не может быть подтверждена.';}
}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['request_recovery'])){
    $started=microtime(true);$email=isset($_POST['admin_email'])?strtolower(trim((string)$_POST['admin_email'])):'';$matched=false;
    try{$matched=$auth->recoveryEmailMatches($email);if($matched)$selfUpdater->requestRecoveryEmail($email);}catch(Exception $e){recSecurityLog($manager->storage(),'recovery_email_request_error',array('email_hash'=>$email!==''?hash('sha256',$email):'','message'=>substr($e->getMessage(),0,300)));}catch(Throwable $e){recSecurityLog($manager->storage(),'recovery_email_request_error',array('email_hash'=>$email!==''?hash('sha256',$email):'','message'=>'internal'));}
    $elapsed=microtime(true)-$started;if($elapsed<0.7)usleep((int)((0.7-$elapsed)*1000000));$requestMessage='Если этот email зарегистрирован как администратор, одноразовая ссылка Recovery отправлена. Проверьте почту.';
}
$action=isset($_GET['action'])?(string)$_GET['action']:'';
if($action!==''){
    $authorized=!empty($_SESSION['ume_recovery_site'])&&$_SESSION['ume_recovery_site']===(string)$config['site_id']&&!empty($_SESSION['ume_recovery_expires'])&&(int)$_SESSION['ume_recovery_expires']>=time();
    if(!$authorized)recJson(array('ok'=>false,'error'=>'Recovery-сессия истекла. Запросите новую ссылку.'),403);
    if($_SERVER['REQUEST_METHOD']==='POST'){$csrf=isset($_POST['csrf'])?$_POST['csrf']:'';$expected=isset($_SESSION['ume_recovery_csrf'])?$_SESSION['ume_recovery_csrf']:'';if(!(function_exists('hash_equals')?hash_equals($expected,$csrf):$expected===$csrf))recJson(array('ok'=>false,'error'=>'CSRF-проверка не пройдена.'),403);}
    try{
        if($action==='status')recJson(array('ok'=>true,'job'=>$manager->publicJob($manager->activeJob()),'applied'=>$manager->availableRollbacks(),'session_expires'=>(int)$_SESSION['ume_recovery_expires']),200);
        if($action==='cancel'){ $j=$manager->activeJob(); recJson(array('ok'=>true,'job'=>$j?$manager->cancel($j['id']):null),200); }
        if($action==='step'){ $j=$manager->activeJob(); recJson(array('ok'=>true,'job'=>$j?$manager->step($j['id']):null),200); }
        if($action==='rollback')recJson(array('ok'=>true,'job'=>$manager->publicJob($manager->startRollback($_POST['patch_id']))),200);
        if($action==='reset_password'){$temporary=substr(UMEUtil::randomHex(16),0,24);$reset=$auth->resetPassword($temporary,true,'recovery_email');recJson(array('ok'=>true,'username'=>$reset['username'],'temporary_password'=>$temporary,'force_password_change'=>true,'message'=>'Временный пароль установлен. Все старые сессии отозваны.'),200);}
        if($action==='logout'){unset($_SESSION['ume_recovery_site'],$_SESSION['ume_recovery_expires'],$_SESSION['ume_recovery_csrf']);session_destroy();header('Location: recovery.php');exit;}
        recJson(array('ok'=>false,'error'=>'Неизвестное действие.'),404);
    }catch(Exception $e){recJson(array('ok'=>false,'error'=>$e->getMessage()),500);}catch(Throwable $e){recJson(array('ok'=>false,'error'=>$e->getMessage()),500);}
}
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Upgrade Recovery</title><link rel="icon" href="./favicon.ico" sizes="any"><link rel="stylesheet" href="assets/app.css?v=<?php echo (int)@filemtime(__DIR__.'/assets/app.css'); ?>"></head><body>
<?php if(!$authorized): ?>
<div class="login-shell"><form class="login-card" method="post"><div class="login-brand"><span>R</span></div><div class="eyebrow">Аварийный доступ</div><h1>Recovery</h1><p>Введите email администратора. Одноразовая ссылка придёт через настроенный центральный Upgrade Manager.</p><label for="recovery-email">Email администратора</label><input id="recovery-email" type="email" name="admin_email" autocomplete="username" required autofocus><input type="hidden" name="request_recovery" value="1"><button class="button primary full" type="submit">Отправить ссылку входа</button><?php if($requestMessage!==''):?><div class="notice ok persistent"><?php echo htmlspecialchars($requestMessage,ENT_QUOTES,'UTF-8');?></div><?php endif;?><?php if($error!==''):?><div class="notice error persistent"><?php echo htmlspecialchars($error,ENT_QUOTES,'UTF-8');?></div><?php endif;?><small class="oauth-note">Ссылка действует 10 минут и только один раз. Если установка обновлена со старой версии и email ещё не привязан, сначала войдите обычным способом и привяжите email в «Безопасности».</small></form></div>
<?php else: ?>
<header class="topbar"><div><strong>Upgrade Recovery</strong><span>v<?php echo htmlspecialchars($config['version']);?></span></div><nav><a href="recovery.php?action=logout">Выйти</a></nav></header>
<main class="page"><div id="notice"></div><section class="hero"><div><h1>Аварийное восстановление</h1><p>Прерывание зависшего процесса, rollback и восстановление доступа к Upgrade Manager.</p></div><button class="danger" id="cancel">Прервать активный процесс</button></section>
<section class="card"><h2>Сброс пароля Upgrade Manager</h2><p>Создаёт временный пароль, отзывает все текущие сессии и требует задать постоянный пароль после следующего входа.</p><button class="button danger" id="reset-password" type="button">Создать временный пароль</button><div id="reset-password-result"></div></section>
<section class="card"><h2>Доступные откаты</h2><div id="rollbacks"></div></section></main>
<div class="process-overlay hidden" id="process" aria-hidden="true"><div class="process-backdrop" aria-hidden="true"></div><section class="process process-dialog" role="dialog" aria-modal="true" aria-labelledby="pt" aria-describedby="pm"><div class="process-head"><div class="process-title-wrap"><span class="process-spinner" aria-hidden="true"></span><div><strong id="pt">Процесс</strong><p id="pm"></p></div></div><span class="process-status" id="ps">Выполняется</span></div><div class="progress"><div id="pb"></div></div><div class="progress-meta"><span id="pp">0%</span><span>Recovery</span></div><p class="process-lock-note" id="pn">Пока процесс не завершён, остальной интерфейс заблокирован.</p><details class="process-details"><summary>Технический журнал процесса</summary><pre id="pl"></pre></details><div class="process-actions"><button class="button danger" id="process-cancel" type="button">Прервать</button></div></section></div>
<script>window.REC={csrf:<?php echo json_encode($_SESSION['ume_recovery_csrf']);?>};</script>
<script>(function(){
var csrf=REC.csrf,job=null,timer=null;
function lockPage(lock){['.topbar','.page'].forEach(function(sel){var el=document.querySelector(sel);if(!el)return;if(lock){el.setAttribute('inert','');el.setAttribute('aria-hidden','true');}else{el.removeAttribute('inert');el.removeAttribute('aria-hidden');}});document.body.classList.toggle('process-modal-open',!!lock);}
function api(a,d){var f=new FormData();Object.keys(d||{}).forEach(function(k){f.append(k,d[k]);});f.append('csrf',csrf);return fetch('recovery.php?action='+a,{method:'POST',body:f,credentials:'same-origin'}).then(function(r){return r.json().then(function(j){if(!r.ok||!j.ok)throw new Error(j.error||'Ошибка');return j;});});}
function note(m){document.getElementById('notice').className='notice error';document.getElementById('notice').textContent=m;}
function statusLabel(s){return s==='running'?'Выполняется':s==='stale'?'Ожидает продолжения':s==='cancelling'?'Прерывается':s==='rolling_back'?'Безопасный откат':s==='completed'?'Завершён':s==='cancelled'?'Прерван':s==='failed'?'Ошибка':s;}
function render(j){job=j;var box=document.getElementById('process'),dialog=box.querySelector('.process-dialog'),cancel=document.getElementById('process-cancel');if(!j){box.classList.add('hidden');box.setAttribute('aria-hidden','true');lockPage(false);return;}box.classList.remove('hidden');box.setAttribute('aria-hidden','false');lockPage(true);document.getElementById('pt').textContent=j.type+' · '+j.id;document.getElementById('pm').textContent=j.message||'';document.getElementById('ps').textContent=statusLabel(j.status);var progress=Math.max(0,Math.min(100,Number(j.progress||0)));document.getElementById('pb').style.width=progress+'%';document.getElementById('pp').textContent=progress+'%';document.getElementById('pl').textContent=(j.log_tail||[]).join('\n');var terminal=['completed','failed','cancelled'].indexOf(j.status)>=0;var canCancel=!terminal&&['running','stale'].indexOf(j.status)>=0&&j.cancel_allowed!==false;cancel.disabled=!canCancel;if(j.status==='cancelling'||j.cancel_requested)cancel.textContent='Прерываем…';else if(j.status==='rolling_back')cancel.textContent='Возвращаем изменения…';else if(!canCancel&&!terminal&&j.type==='rollback')cancel.textContent='Критический этап…';else cancel.textContent='Прервать';document.getElementById('pn').textContent=j.status==='rolling_back'?'Прерывание принято. Recovery дождётся безопасного возврата изменений.':(!canCancel&&!terminal&&j.type==='rollback'?'Критическое восстановление нельзя остановить посередине.':'Пока процесс не завершён, остальной интерфейс заблокирован.');dialog.classList.toggle('terminal',terminal);dialog.classList.toggle('success',j.status==='completed');dialog.classList.toggle('error',j.status==='failed');dialog.classList.toggle('cancelled',j.status==='cancelled');if(timer)clearTimeout(timer);timer=null;if(!terminal&&j.status!=='stale')timer=setTimeout(step,300);else if(terminal)timer=setTimeout(load,850);}
function step(){if(!job)return;api('step',{}).then(function(r){render(r.job);}).catch(function(e){document.getElementById('pm').textContent='Ошибка связи: '+e.message;timer=setTimeout(step,1200);});}
function load(){fetch('recovery.php?action=status',{credentials:'same-origin'}).then(function(r){return r.json();}).then(function(r){if(!r.ok)throw new Error(r.error);render(r.job);var a=r.applied||{},html='';Object.keys(a).reverse().forEach(function(id){html+='<div class="report"><b>'+id+'</b> · '+(a[id].name||'')+' '+(a[id].version||'')+' <button class="danger small rollback" data-id="'+id+'">Откатить</button></div>';});document.getElementById('rollbacks').innerHTML=html||'<p>Доступных откатов нет.</p>';}).catch(function(e){note(e.message);});}
function interrupt(){var cancel=document.getElementById('process-cancel');if(!job||cancel.disabled)return;if(timer)clearTimeout(timer);timer=null;cancel.disabled=true;cancel.textContent='Прерываем…';document.getElementById('pm').textContent='Запрашиваем безопасное прерывание процесса…';api('cancel',{}).then(function(r){render(r.job);}).catch(function(e){document.getElementById('pm').textContent='Не удалось прервать: '+e.message;note(e.message);timer=setTimeout(step,1000);});}
document.getElementById('process-cancel').onclick=interrupt;document.getElementById('cancel').onclick=function(){if(job)interrupt();else note('Активного процесса сейчас нет.');};document.addEventListener('click',function(e){if(e.target.classList.contains('rollback')&&confirm('Запустить откат '+e.target.dataset.id+'?'))api('rollback',{patch_id:e.target.dataset.id}).then(function(r){render(r.job);}).catch(function(x){note(x.message);});});var resetPassword=document.getElementById('reset-password');if(resetPassword)resetPassword.onclick=function(){if(!confirm('Сбросить пароль Upgrade Manager и отключить все текущие сессии?'))return;resetPassword.disabled=true;api('reset_password',{}).then(function(r){var box=document.getElementById('reset-password-result');box.textContent='';var report=document.createElement('div');report.className='report';var user=document.createElement('div');user.appendChild(document.createTextNode('Логин: '+(r.username||'')));var pass=document.createElement('div');pass.appendChild(document.createTextNode('Временный пароль: '+(r.temporary_password||'')));var hint=document.createElement('small');hint.textContent='Скопируйте пароль сейчас. После входа потребуется задать постоянный.';report.appendChild(user);report.appendChild(pass);report.appendChild(hint);box.appendChild(report);}).catch(function(e){note(e.message);}).then(function(){resetPassword.disabled=false;});};load();
})();</script>
<?php endif;?></body></html>
